<script setup>
import { ref } from 'vue';
import { Store } from '../../store';
import Icon from '../ui/EditionIcon.vue';
const tab=ref('Appearance'),busy=ref(false);
const prefs=ref({density:'comfortable',reduceMotion:false,paperWidth:'80',receiptFooter:'Thank you for shopping with us.',staffDiscountLimit:0,...Store.state.selectedCompany?.preferences});
async function save(){if(!Store.can('companyWrite')||!Store.state.online)return;busy.value=true;try{if(Store.can('costsWrite')&&(!Number.isFinite(Number(prefs.value.staffDiscountLimit))||Number(prefs.value.staffDiscountLimit)<0||Number(prefs.value.staffDiscountLimit)>100))throw new Error('Staff discount limit must be between 0 and 100%.');await Store.updatePreferences({...prefs.value,theme:'light'});Store.notify('Preferences saved.');}catch(e){Store.notify(e.message,'error');}finally{busy.value=false;}}
</script>
<template><div class="ed-page"><header class="ed-page-head"><div><div class="ed-eyebrow">ADMINISTRATION / PREFERENCES</div><h1>Make it your own.</h1><p>The details that make this workspace feel like your shop.</p></div><button class="ed-btn primary" :disabled="busy||!Store.state.online" @click="save"><Icon name="check" />{{ busy?'Saving…':'Save changes' }}</button></header><div class="ed-settings"><nav class="ed-settings-nav" aria-label="Preference sections"><button v-for="section in ['Appearance','Receipts','Checkout']" :key="section" :class="{active:tab===section}" @click="tab=section">{{ section }}</button><router-link to="/companies" class="ed-link" style="padding:12px">Store profile<Icon name="arrow" /></router-link><router-link to="/templates" class="ed-link" style="padding:12px">Invoice templates<Icon name="arrow" /></router-link></nav><section><template v-if="tab==='Appearance'"><h2>Edition: room to breathe.</h2><p class="ed-muted" style="margin-top:8px">Forest, paper and a familiar left navigation. Open surfaces keep the focus on your work.</p><div class="ed-swatches"><div v-for="(color,name) in {'Forest':'#164e42','Ink':'#172c26','Paper':'#fbfbf8','Mist':'#edf2e9','Citrus':'#d9f0a0'}" :key="name"><i :style="{background:color,border:'1px solid var(--ed-line)'}"></i><small>{{ name }}<br>{{ color }}</small></div></div><div class="ed-section"><h2>Workspace density</h2><div class="ed-actions" style="margin-top:20px"><label><input v-model="prefs.density" type="radio" value="comfortable"> Comfortable</label><label><input v-model="prefs.density" type="radio" value="compact"> Compact</label></div><label class="ed-switch"><span><strong>Reduce motion</strong><small>Keep transitions quiet and immediate.</small></span><input v-model="prefs.reduceMotion" type="checkbox"></label></div></template><template v-else-if="tab==='Receipts'"><h2>Receipt preferences</h2><p class="ed-muted" style="margin:8px 0 24px">Print the saved sale from checkout or the paid sales ledger.</p><div class="ed-form-grid"><label class="ed-field"><span>Paper width</span><select v-model="prefs.paperWidth"><option value="80">80 mm thermal</option><option value="58">58 mm thermal</option></select></label><label class="ed-field wide"><span>Footer message</span><textarea v-model="prefs.receiptFooter" maxlength="500"></textarea></label></div><div class="ed-notice"><Icon name="printer" /><div>Choose the matching paper size in your printer's settings. Reprinting uses the original receipt and never creates another sale.</div></div><router-link to="/pos" class="ed-link">Open checkout receipts<Icon name="arrow" /></router-link></template><template v-else><h2>At the counter</h2><label v-if="Store.permissions().owner" class="ed-field ed-editor-section"><span>Staff discount limit (%)</span><input v-model.number="prefs.staffDiscountLimit" type="number" min="0" max="100" step="0.01"><small>Default 0%. Staff cannot change catalog prices or tax. Managers must record a reason above this limit.</small></label><p v-else class="ed-notice">Staff discount limit: {{ Store.state.selectedCompany?.preferences?.staffDiscountLimit || 0 }}%. Ask an owner to change this policy.</p><div class="ed-row"><div><strong>Cash, QR Pay & external card</strong><small>Cash validates received amount; QR/card require merchant confirmation.</small></div><span class="ed-pill">Enabled</span></div><div class="ed-row"><div><strong>Durable orders</strong><small>Cart and held orders stay on this signed-in device after refresh.</small></div><span class="ed-pill">Enabled</span></div><div class="ed-row"><div><strong>Offline receipt queue</strong><small>Pending receipts remain on this device until the server confirms the save.</small></div><span class="ed-pill">Enabled</span></div><div class="ed-notice warning"><Icon name="cloud" /><div>Offline selling needs this store to have been loaded on the device. Disconnected tills share no live stock count. Stock shortages are flagged when offline receipts sync.</div></div><router-link to="/companies" class="ed-link">Manage tax & payment QR<Icon name="arrow" /></router-link></template></section></div></div></template>
